INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (62, 'tt4633694', true, 62, '2026-11-09', 'Spider-Man: Into the Spider-Verse', 2018, 'PG', '1h 57m', 117, 8.4, 824122, 87, 'Bob Persichetti, Peter Ramsey, Rodney Rothman', 'Phil Lord, Rodney Rothman', 'Shameik Moore, Jake Johnson, Hailee Steinfeld, Mahershala Ali', 'Animation, Action, Adventure, Family, Fantasy, Sci-Fi', 'English, Spanish', 'United States', 'https://www.imdb.com/title/tt4633694/', 'https://m.media-amazon.com/images/M/MV5BMjMwNDkxMTgzOF5BMl5BanBnXkFtZTgwNTkwNTQ3NjM@._V1_.jpg', 'Teen Miles Morales becomes the Spider-Man of his universe and must join with five spider-powered individuals from other dimensions to stop a threat for all realities.', 'O adolescente Miles Morales se torna o Homem-Aranha de seu universo e deve se juntar a cinco indivíduos com poderes de aranha de outras dimensões para impedir uma ameaça para todas as realidades.', 'Teen Miles Morales becomes the Spider-Man of his universe and must join with five spider-powered individuals from other dimensions to stop a threat for all realities.', 'El adolescente Miles Morales se convierte en el Spider-Man de su universo y debe unirse a cinco individuos de otras dimensiones con poderes de arañas para detener una amenaza para todas las realidades.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (63, 'tt0405094', true, 63, '2026-11-09', 'Das Leben der Anderen', 2006, 'R', '2h 17m', 137, 8.4, 448920, 89, 'Florian Henckel von Donnersmarck', 'Florian Henckel von Donnersmarck', 'Ulrich Mühe, Martina Gedeck, Sebastian Koch, Ulrich Tukur', 'Drama, Mystery, Thriller', 'German', 'Germany, France', 'https://www.imdb.com/title/tt0405094/', 'https://m.media-amazon.com/images/M/MV5BYjM1N2Q0YWEtN2E5MC00NDM3LTk2NTEtMTc1NTk5OTA5ZGIzXkEyXkFqcGc@._V1_.jpg', 'In 1984 East Berlin, an agent of the secret police conducting surveillance on a writer and his lover finds himself becoming increasingly absorbed by their lives.', 'Em 1984, em Berlim Oriental, um agente da polícia secreta que vigiava um escritor e a sua amante vê-se cada vez mais absorvido pelas suas vidas.', 'In 1984 East Berlin, an agent of the secret police conducting surveillance on a writer and his lover finds himself becoming increasingly absorbed by their lives.', 'En 1984, en Berlín Oriental, un agente de la policía secreta que vigila a un escritor y a su amante se ve cada vez más absorbido por sus vidas.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (64, 'tt33764258', true, 66, '2026-11-09', 'The Odyssey', 2026, 'R', '2h 52m', 172, 8.4, 552704, 88, 'Christopher Nolan', 'Christopher Nolan, Homer', 'Matt Damon, Tom Holland, Anne Hathaway, Robert Pattinson', 'Action, Adventure, Fantasy', 'English, Greek', 'United Kingdom, United States, Canada, New Zealand, Iceland', 'https://www.imdb.com/title/tt33764258/', 'https://m.media-amazon.com/images/M/MV5BNTcyNmJlZmQtNDUwYy00NDBjLTg1NGQtYTY2Y2UxMWM3NmI1XkEyXkFqcGc@._V1_.jpg', 'After the Trojan War, Odysseus faces a dangerous voyage back to Ithaca, meeting creatures like the Cyclops Polyphemus, Sirens, and Calypso along the way.', 'Após a Guerra de Tróia, Odisseu enfrenta uma perigosa viagem de volta a Ítaca, encontrando criaturas como o Ciclope Polifemo, as Sereias e o Calipso ao longo do caminho.', 'After the Trojan War, Odysseus faces a dangerous voyage back to Ithaca, meeting creatures like the Cyclops Polyphemus, Sirens, and Calypso along the way.', 'Después de la Guerra de Troya, Odiseo se enfrenta a un peligroso viaje de regreso a Ítaca, donde se encontrará con criaturas como el cíclope Polifemo, las sirenas y Calipso en el camino.');
