INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (68, 'tt0361748', true, 68, '2026-11-09', 'Inglourious Basterds', 2009, 'R', '2h 33m', 153, 8.4, 1829386, 69, 'Quentin Tarantino', 'Quentin Tarantino', 'Brad Pitt, Diane Kruger, Eli Roth, Mélanie Laurent', 'Drama, War', 'English, German, French, Italian', 'United States, Germany', 'https://www.imdb.com/title/tt0361748/', 'https://m.media-amazon.com/images/M/MV5BODZhMWJlNjYtNDExNC00MTIzLTllM2ItOGQ2NGVjNDQ3MzkzXkEyXkFqcGc@._V1_.jpg', 'In Nazi-occupied France during World War II, a plan to assassinate Nazi leaders by a group of Jewish U.S. soldiers coincides with a theatre owner''s vengeful plans for the same.', 'Na França ocupada pelos nazistas durante a Segunda Guerra Mundial, um plano para assassinar líderes nazistas por um grupo de soldados judeus dos EUA coincide com os planos vingativos de um proprietário de teatro para o mesmo.', 'In Nazi-occupied France during World War II, a plan to assassinate Nazi leaders by a group of Jewish U.S. soldiers coincides with a theatre owner''s vengeful plans for the same.', 'En la Francia ocupada por los nazis durante la Segunda Guerra Mundial, un plan para asesinar a líderes nazis por parte de un grupo de soldados judíos estadounidenses coincide con los planes vengativos del propietario de un teatro para lo mismo.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (69, 'tt0081505', true, 69, '2026-11-09', 'The Shining', 1980, 'R', '2h 26m', 146, 8.4, 1253476, 68, 'Stanley Kubrick', 'Stephen King, Stanley Kubrick, Diane Johnson', 'Jack Nicholson, Shelley Duvall, Danny Lloyd, Scatman Crothers', 'Drama, Horror', 'English', 'United Kingdom, United States', 'https://www.imdb.com/title/tt0081505/', 'https://m.media-amazon.com/images/M/MV5BNmM5ZThhY2ItOGRjOS00NzZiLWEwYTItNDgyMjFkOTgxMmRiXkEyXkFqcGc@._V1_.jpg', 'Aspiring author Jack Torrance must survive winter isolation at the Overlook Hotel, but writer''s block and supernatural forces threaten his sanity, all while his psychic son Danny sees horrors that predict the family''s violent unraveling.', 'O aspirante a autor Jack Torrance deve sobreviver ao isolamento de inverno no Overlook Hotel, mas o bloqueio de escritor e as forças sobrenaturais ameaçam sua sanidade, enquanto seu filho psíquico Danny vê horrores que preveem o violento desmoronamento da família.', 'Aspiring author Jack Torrance must survive winter isolation at the Overlook Hotel, but writer''s block and supernatural forces threaten his sanity, all while his psychic son Danny sees horrors that predict the family''s violent unraveling.', 'El aspirante a autor Jack Torrance debe sobrevivir al aislamiento invernal en el Hotel Overlook, pero el bloqueo del escritor y fuerzas sobrenaturales amenazan su cordura, mientras su hijo psíquico Danny ve horrores que predicen el violento desmoronamiento de la familia.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (70, 'tt0032553', true, 70, '2026-11-09', 'The Great Dictator', 1940, 'G', '2h 5m', 125, 8.4, 261351, NULL, 'Charles Chaplin', 'Charles Chaplin', 'Charles Chaplin, Paulette Goddard, Jack Oakie, Reginald Gardiner', 'Comedy, Drama, War', 'English, Esperanto, Latin', 'United States', 'https://www.imdb.com/title/tt0032553/', 'https://m.media-amazon.com/images/M/MV5BNDE3NmIzZjItMzNlMi00YWI0LWIzMTktMGRkMWE0ZDhiMmM5XkEyXkFqcGc@._V1_.jpg', 'Dictator Adenoid Hynkel tries to expand his empire while a poor Jewish barber tries to avoid persecution from Hynkel''s regime.', 'O ditador Adenoid Hynkel tenta expandir seu império enquanto um pobre barbeiro judeu tenta evitar a perseguição do regime de Hynkel.', 'Dictator Adenoid Hynkel tries to expand his empire while a poor Jewish barber tries to avoid persecution from Hynkel''s regime.', 'El dictador Adenoid Hynkel intenta expandir su imperio mientras un barbero judío pobre intenta evitar la persecución del régimen de Hynkel.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (71, 'tt0090605', true, 71, '2026-11-09', 'Aliens', 1986, 'R', '2h 17m', 137, 8.4, 852395, 84, 'James Cameron', 'James Cameron, David Giler, Walter Hill, Dan O''Bannon, Ronald Shusett', 'Sigourney Weaver, Michael Biehn, Carrie Henn, Paul Reiser', 'Action, Adventure, Horror, Sci-Fi, Thriller', 'English, Spanish', 'United Kingdom, United States', 'https://www.imdb.com/title/tt0090605/', 'https://m.media-amazon.com/images/M/MV5BN2ZiMmQ0YWItN2IwZS00Y2NhLWE0NzQtNGNiOGFjN2U4MWNmXkEyXkFqcGc@._V1_.jpg', 'Decades after surviving the Nostromo incident, Ellen Ripley is sent out to re-establish contact with a terraforming colony but finds herself battling the Alien Queen and her offspring.', 'Décadas depois de sobreviver ao incidente de Nostromo, Ellen Ripley é enviada para restabelecer contato com uma colônia de terraformação, mas se vê lutando contra a Rainha Alienígena e seus descendentes.', 'Decades after surviving the Nostromo incident, Ellen Ripley is sent out to re-establish contact with a terraforming colony but finds herself battling the Alien Queen and her offspring.', 'Décadas después de sobrevivir al incidente de Nostromo, Ellen Ripley es enviada a restablecer el contacto con una colonia de terraformación, pero se encuentra luchando contra la Reina Alien y su descendencia.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (72, 'tt0057565', true, 72, '2026-11-09', 'Tengoku to jigoku', 1963, 'Not Rated', '2h 23m', 143, 8.4, 74451, 90, 'Akira Kurosawa', 'Hideo Oguni, Ryûzô Kikushima, Eijirô Hisaita, Akira Kurosawa, Evan Hunter', 'Toshirō Mifune, Yutaka Sada, Tatsuya Nakadai, Kyōko Kagawa', 'Crime, Drama, Mystery, Thriller', 'Japanese', 'Japan', 'https://www.imdb.com/title/tt0057565/', 'https://m.media-amazon.com/images/M/MV5BMGJiNzllYjktODAzNS00OGUzLTlmY2MtMjA2ZTZhYTY1OTc4XkEyXkFqcGc@._V1_.jpg', 'An executive of a Yokohama shoe company becomes a victim of extortion when his chauffeur''s son is kidnapped by mistake and held for ransom.', 'Um executivo de uma empresa de calçados de Yokohama é vítima de extorsão quando o filho de seu motorista é sequestrado por engano e pedido resgate.', 'An executive of a Yokohama shoe company becomes a victim of extortion when his chauffeur''s son is kidnapped by mistake and held for ransom.', 'Un ejecutivo de una empresa de calzado de Yokohama es víctima de extorsión cuando el hijo de su chófer es secuestrado por error y retenido para pedir un rescate.');
