INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (148, 'tt0089881', true, 148, '2026-11-09', 'Ran', 1985, 'R', '2h 40m', 160, 8.2, 155919, 97, 'Akira Kurosawa', 'Akira Kurosawa, Hideo Oguni, Masato Ide, William Shakespeare', 'Tatsuya Nakadai, Akira Terao, Jinpachi Nezu, Daisuke Ryû', 'Action, Drama, War', 'Japanese', 'Japan, France', 'https://www.imdb.com/title/tt0089881/', 'https://m.media-amazon.com/images/M/MV5BZDk2NDY5YjktMjEyMC00OTJhLTkzM2EtY2Q4Y2RjYzc2Yjk4XkEyXkFqcGc@._V1_.jpg', 'In Medieval Japan, an elderly warlord retires, handing over his empire to his three sons. However, he vastly underestimates how the new-found power will corrupt them and cause them to turn on each other...and him.', 'No Japão Medieval, um senhor da guerra idoso se aposenta, entregando seu império aos seus três filhos. No entanto, ele subestima enormemente como o poder recém-descoberto irá corrompê-los e fazer com que se voltem uns contra os outros... e contra ele.', 'In Medieval Japan, an elderly warlord retires, handing over his empire to his three sons. However, he vastly underestimates how the new-found power will corrupt them and cause them to turn on each other...and him.', 'En el Japón medieval, un anciano señor de la guerra se retira y entrega su imperio a sus tres hijos. Sin embargo, subestima enormemente cómo el nuevo poder los corromperá y hará que se vuelvan unos contra otros... y contra él.');
