INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (161, 'tt4729430', true, 161, '2026-11-09', 'Klaus', 2019, 'PG', '1h 36m', 96, 8.2, 244806, 65, 'Sergio Pablos, Carlos Martínez López', 'Sergio Pablos, Jim Mahoney, Zach Lewis', 'Jason Schwartzman, J.K. Simmons, Rashida Jones, Will Sasso', 'Animation, Adventure, Comedy, Family, Fantasy', 'English, Saami', 'Spain, United Kingdom, United States, Austria, Canada, France', 'https://www.imdb.com/title/tt4729430/', 'https://m.media-amazon.com/images/M/MV5BZDA4ODhlMzctNGRmYi00NmViLTkxZGYtZjRkNGQ5YzYwYWVlXkEyXkFqcGc@._V1_.jpg', 'A simple act of kindness always sparks another, even in a frozen, faraway place. When Smeerensburg''s new postman, Jesper, befriends toymaker Klaus, their gifts melt an age-old feud and deliver a sleigh full of holiday traditions.', 'Um simples ato de bondade sempre desperta outro, mesmo em um lugar congelado e distante. Quando o novo carteiro de Smeerensburg, Jesper, faz amizade com o fabricante de brinquedos Klaus, seus presentes derretem uma antiga rixa e entregam um trenó cheio de tradições natalinas.', 'A simple act of kindness always sparks another, even in a frozen, faraway place. When Smeerensburg''s new postman, Jesper, befriends toymaker Klaus, their gifts melt an age-old feud and deliver a sleigh full of holiday traditions.', 'Un simple acto de bondad siempre despierta a otro, incluso en un lugar congelado y lejano. Cuando el nuevo cartero de Smeerensburg, Jesper, se hace amigo del fabricante de juguetes Klaus, sus regalos derriten una antigua enemistad y entregan un trineo lleno de tradiciones navideñas.');
