INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (157, 'tt0268978', true, 157, '2026-11-09', 'A Beautiful Mind', 2001, 'PG-13', '2h 15m', 135, 8.2, 1068304, 72, 'Ron Howard', 'Akiva Goldsman, Sylvia Nasar', 'Russell Crowe, Ed Harris, Jennifer Connelly, Christopher Plummer', 'Biography, Drama, Mystery', 'English', 'United States', 'https://www.imdb.com/title/tt0268978/', 'https://m.media-amazon.com/images/M/MV5BYjgzNjFkMmItOGJhNi00NWM3LWJlYTUtNDExMGQ3ZTI3NjJkXkEyXkFqcGc@._V1_.jpg', 'A mathematical genius, John Nash made an astonishing discovery early in his career and stood on the brink of international acclaim. But Nash soon found himself on a harrowing journey of self-discovery.', 'Um gênio da matemática, John Nash fez uma descoberta surpreendente no início de sua carreira e ficou à beira da aclamação internacional. Mas Nash logo se viu numa jornada angustiante de autodescoberta.', 'A mathematical genius, John Nash made an astonishing discovery early in his career and stood on the brink of international acclaim. But Nash soon found himself on a harrowing journey of self-discovery.', 'Un genio matemático, John Nash hizo un descubrimiento asombroso al principio de su carrera y estuvo al borde de la aclamación internacional. Pero Nash pronto se encontró en un angustioso viaje de autodescubrimiento.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (169, 'tt1305806', true, 169, '2026-11-09', 'El secreto de sus ojos', 2009, 'R', '2h 9m', 129, 8.2, 246845, 80, 'Juan José Campanella', 'Eduardo Sacheri, Juan José Campanella', 'Ricardo Darín, Soledad Villamil, Pablo Rago, Carla Quevedo', 'Drama, Mystery, Romance, Thriller', 'Spanish', 'Argentina, Spain', 'https://www.imdb.com/title/tt1305806/', 'https://m.media-amazon.com/images/M/MV5BMTgwNTI3OTczOV5BMl5BanBnXkFtZTcwMTM3MTUyMw@@._V1_.jpg', 'A retired court investigator revisits a decades old murder while trying to finish the story that has followed him ever since, forcing old evidence and unfinished feelings back into the light.', 'Um investigador aposentado da corte revisita um assassinato de décadas enquanto tenta terminar a história que o segue desde então, forçando evidências antigas e sentimentos inacabados a voltar à luz.', 'A retired court investigator revisits a decades old murder while trying to finish the story that has followed him ever since, forcing old evidence and unfinished feelings back into the light.', 'Un investigador judicial retirado revisita un asesinato de hace décadas mientras trata de terminar la historia que lo ha seguido desde entonces, sacando a la luz viejas pruebas y sentimientos inconclusos.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (170, 'tt0031381', true, 170, '2026-11-09', 'Gone with the Wind', 1939, 'G', '3h 58m', 238, 8.2, 360247, 97, 'Victor Fleming', 'Margaret Mitchell, Sidney Howard, Oliver H.P. Garrett, Ben Hecht, Jo Swerling, John Van Druten', 'Clark Gable, Vivien Leigh, Thomas Mitchell, Barbara O''Neil', 'Drama, Romance, War', 'English', 'United States', 'https://www.imdb.com/title/tt0031381/', 'https://m.media-amazon.com/images/M/MV5BYmYxZTE3YzMtYmE2Yy00NmFlLTkzYTAtYTAzN2IzNDFkN2E0XkEyXkFqcGc@._V1_.jpg', 'A sheltered and manipulative Southern belle and a roguish profiteer face off in a turbulent romance as the society around them crumbles with the end of slavery and is rebuilt during the Civil War and Reconstruction periods.', 'Uma bela sulista protegida e manipuladora e um aproveitador malandro se enfrentam em um romance turbulento à medida que a sociedade ao seu redor desmorona com o fim da escravidão e é reconstruída durante os períodos da Guerra Civil e da Reconstrução.', 'A sheltered and manipulative Southern belle and a roguish profiteer face off in a turbulent romance as the society around them crumbles with the end of slavery and is rebuilt during the Civil War and Reconstruction periods.', 'Una bella sureña protegida y manipuladora y un especulador pícaro se enfrentan en un romance turbulento a medida que la sociedad que los rodea se desmorona con el fin de la esclavitud y se reconstruye durante los períodos de la Guerra Civil y la Reconstrucción.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (181, 'tt0050212', true, 181, '2026-11-09', 'The Bridge on the River Kwai', 1957, 'PG', '2h 41m', 161, 8.1, 252833, 88, 'David Lean', 'Pierre Boulle, Carl Foreman, Michael Wilson', 'William Holden, Alec Guinness, Jack Hawkins, Sessue Hayakawa', 'Adventure, Drama, War', 'English, Japanese, Thai', 'United Kingdom, United States', 'https://www.imdb.com/title/tt0050212/', 'https://m.media-amazon.com/images/M/MV5BNzdkYmU2YmItNmZiYy00OWQyLTg0YWYtZmUxM2U3YTRiNTQ1XkEyXkFqcGc@._V1_.jpg', 'British POWs are forced to build a railway bridge across the river Kwai for their Japanese captors in occupied Burma, not knowing that the allied forces are planning a daring commando raid through the jungle to destroy it.', 'Os prisioneiros de guerra britânicos são forçados a construir uma ponte ferroviária sobre o rio Kwai para os seus captores japoneses na Birmânia ocupada, sem saber que as forças aliadas estão a planear um ataque ousado através da selva para a destruir.', 'British POWs are forced to build a railway bridge across the river Kwai for their Japanese captors in occupied Burma, not knowing that the allied forces are planning a daring commando raid through the jungle to destroy it.', 'Los prisioneros de guerra británicos se ven obligados a construir un puente ferroviario sobre el río Kwai para sus captores japoneses en la Birmania ocupada, sin saber que las fuerzas aliadas están planeando una audaz incursión de comandos a través de la selva para destruirla.');
