INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (56, 'tt0021749', true, 56, '2026-11-09', 'City Lights', 1931, 'G', '1h 27m', 87, 8.5, 219171, 99, 'Charles Chaplin', 'Charles Chaplin, Harry Carr, Harry Crocker', 'Charles Chaplin, Virginia Cherrill, Florence Lee, Harry Myers', 'Comedy, Drama, Romance', 'None, English', 'United States', 'https://www.imdb.com/title/tt0021749/', 'https://m.media-amazon.com/images/M/MV5BM2U4NjgzODUtODkyOC00YTE2LTlhNTItYzFlYmM1NTEzZDA2XkEyXkFqcGc@._V1_.jpg', 'With the aid of a wealthy erratic tippler, a dewy-eyed tramp who has fallen in love with a blind flower girl accumulates money to be able to help her medically.', 'Com a ajuda de um rico bebedor errático, um vagabundo de olhos úmidos que se apaixonou por uma florista cega acumula dinheiro para poder ajudá-la clinicamente.', 'With the aid of a wealthy erratic tippler, a dewy-eyed tramp who has fallen in love with a blind flower girl accumulates money to be able to help her medically.', 'Con la ayuda de un rico bebedor errático, un vagabundo de ojos húmedos que se ha enamorado de una florista ciega acumula dinero para poder ayudarla médicamente.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (57, 'tt0078788', true, 57, '2026-11-09', 'Apocalypse Now', 1979, 'R', '2h 27m', 147, 8.4, 781813, 94, 'Francis Ford Coppola', 'John Milius, Francis Ford Coppola, Michael Herr, Joseph Conrad', 'Martin Sheen, Marlon Brando, Robert Duvall, Frederic Forrest', 'Drama, Mystery, War', 'English, French, Vietnamese', 'United States', 'https://www.imdb.com/title/tt0078788/', 'https://m.media-amazon.com/images/M/MV5BZDhiMTljYjYtODc1Yy00MmEwLTg2OTYtYmE1YTRmNDE4MmEwXkEyXkFqcGc@._V1_.jpg', 'A U.S. Army officer serving in Vietnam is tasked with assassinating a renegade Special Forces Colonel who sees himself as a god.', 'Um oficial do Exército dos EUA servindo no Vietnã é encarregado de assassinar um coronel renegado das Forças Especiais que se considera um deus.', 'A U.S. Army officer serving in Vietnam is tasked with assassinating a renegade Special Forces Colonel who sees himself as a god.', 'Un oficial del ejército estadounidense que sirve en Vietnam tiene la tarea de asesinar a un coronel renegado de las fuerzas especiales que se ve a sí mismo como un dios.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (58, 'tt4154756', true, 58, '2026-11-09', 'Avengers: Infinity War', 2018, 'PG-13', '2h 29m', 149, 8.4, 1423234, 68, 'Anthony Russo, Joe Russo', 'Christopher Markus, Stephen McFeely, Stan Lee, Jack Kirby, Joe Simon, Steve Englehart, Steve Gan, Bill Mantlo, Keith Giffen, Jim Starlin, Larry Lieber, Don Heck', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans', 'Action, Adventure, Sci-Fi', 'English', 'United States, Norway', 'https://www.imdb.com/title/tt4154756/', 'https://m.media-amazon.com/images/M/MV5BMjMxNjY2MDU1OV5BMl5BanBnXkFtZTgwNzY1MTUwNTM@._V1_.jpg', 'The Avengers and their allies must be willing to sacrifice all in an attempt to defeat the powerful Thanos before his blitz of devastation and ruin puts an end to the universe.', 'Os Vingadores e seus aliados devem estar dispostos a sacrificar tudo na tentativa de derrotar o poderoso Thanos antes que sua onda de devastação e ruína ponha fim ao universo.', 'The Avengers and their allies must be willing to sacrifice all in an attempt to defeat the powerful Thanos before his blitz of devastation and ruin puts an end to the universe.', 'Los Vengadores y sus aliados deben estar dispuestos a sacrificarlo todo en un intento de derrotar al poderoso Thanos antes de que su bombardeo de devastación y ruina ponga fin al universo.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (59, 'tt0209144', true, 59, '2026-11-09', 'Memento', 2000, 'R', '1h 53m', 113, 8.4, 1466528, 83, 'Christopher Nolan', 'Christopher Nolan, Jonathan Nolan', 'Guy Pearce, Carrie-Anne Moss, Joe Pantoliano, Mark Boone Junior', 'Mystery, Thriller', 'English', 'United States', 'https://www.imdb.com/title/tt0209144/', 'https://m.media-amazon.com/images/M/MV5BMGQ3Y2Q4NjktN2E4Ny00Y2Q2LTliZDUtZTNiNjRhY2I0NGIyXkEyXkFqcGc@._V1_.jpg', 'A former insurance investigator who now suffers from anterograde amnesia uses notes and tattoos to hunt down his wife''s murderer.', 'Um ex-investigador de seguros que agora sofre de amnésia anterógrada usa anotações e tatuagens para caçar o assassino de sua esposa.', 'A former insurance investigator who now suffers from anterograde amnesia uses notes and tattoos to hunt down his wife''s murderer.', 'Un ex investigador de seguros que ahora sufre de amnesia anterógrada utiliza notas y tatuajes para cazar al asesino de su esposa.');
INSERT INTO public.movie (id_movie, imdb_id, is_in_top250, current_rank, data_upd, original_title, year, certificate, duration, duration_minutes, rating, vote_count, metascore, directors, writers, stars, genres, languages, countries, link, poster_url, plot, plot_pt, plot_en, plot_es) VALUES (60, 'tt15239678', true, 60, '2026-11-09', 'Dune: Part Two', 2024, 'PG-13', '2h 46m', 166, 8.4, 805193, 79, 'Denis Villeneuve', 'Denis Villeneuve, Jon Spaihts, Frank Herbert', 'Timothée Chalamet, Zendaya, Rebecca Ferguson, Javier Bardem', 'Action, Adventure, Drama, Sci-Fi', 'English, American Sign Language', 'United States, Canada, United Arab Emirates, Hungary, Italy, New Zealand, Jordan', 'https://www.imdb.com/title/tt15239678/', 'https://m.media-amazon.com/images/M/MV5BNTc0YmQxMjEtODI5MC00NjFiLTlkMWUtOGQ5NjFmYWUyZGJhXkEyXkFqcGc@._V1_.jpg', 'Paul Atreides unites with the Fremen while on a warpath of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the universe, he endeavors to prevent a terrible future.', 'Paul Atreides se une aos Fremen enquanto está em guerra de vingança contra os conspiradores que destruíram sua família. Enfrentando uma escolha entre o amor de sua vida e o destino do universo, ele se esforça para evitar um futuro terrível.', 'Paul Atreides unites with the Fremen while on a warpath of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the universe, he endeavors to prevent a terrible future.', 'Paul Atreides se une a los Fremen mientras emprende una guerra de venganza contra los conspiradores que destruyeron a su familia. Ante la elección entre el amor de su vida y el destino del universo, se esfuerza por evitar un futuro terrible.');
